PROVA_FINESTRA = os.environ.get("COMUNITAT_PROVA_FINESTRA", "")


def hi_ha_pantalla():
    return os.name == "nt" or sys.platform == "darwin" or bool(os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"))


def hi_ha_finestra():
    """Hi ha tkinter i una pantalla on mostrar la finestreta de l'adreça?"""
    if not hi_ha_pantalla():
        return False
    try:
        import tkinter  # noqa: F401
        return True
    except Exception:  # noqa: BLE001
        return False


def avis_finestra(titol, text):
    """Un missatge d'error en una finestra (per a l'executable de Windows, que no té terminal)."""
    try:
        import tkinter as tk
        from tkinter import messagebox
        r = tk.Tk()
        r.withdraw()
        messagebox.showerror(titol, text)
        r.destroy()
    except Exception:  # noqa: BLE001
        pass


def obrir_carpeta(path):
    try:
        if os.name == "nt":
            os.startfile(str(path))  # noqa: S606
        else:
            import subprocess
            subprocess.Popen(["open" if sys.platform == "darwin" else "xdg-open", str(path)])
    except Exception:  # noqa: BLE001
        pass


def dades_finestra():
    """On guarda la finestra pròpia el que recorda el navegador (qui ha entrat, l'idioma, el tema)."""
    if os.name == "nt":
        base = Path(os.environ.get("LOCALAPPDATA") or Path.home() / "AppData" / "Local") / "LaComunitat"
    else:
        base = Path(os.environ.get("XDG_DATA_HOME") or Path.home() / ".local" / "share") / "comunitat-del-anell"
    d = base / "finestra"
    d.mkdir(parents=True, exist_ok=True)
    return d


def prova_feta(titol):
    """Per a les proves automàtiques: apunta que l'app s'ha carregat a la finestra pròpia."""
    try:
        Path(PROVA_FINESTRA).write_text(f"ok {titol}", encoding="utf-8")
    except OSError:
        pass


# ---------------------------------------------------------------- la finestra pròpia
def finestra_app(port, idioma):
    """Obri l'app en una finestra pròpia i espera fins que es tanca.
    Torna False, sense haver obert res, si en aquest ordinador no es pot."""
    url = f"http://localhost:{port}/"
    if not hi_ha_pantalla():
        return False
    if os.name == "nt" or sys.platform == "darwin":
        return _finestra_pywebview(url, idioma)
    return _finestra_gtk(url, idioma)


def _finestra_pywebview(url, idioma):
    """Windows (i Mac, si hi ha pywebview): la finestra amb pywebview. A Windows només amb WebView2;
    l'antic motor d'Internet Explorer no pot mostrar l'app."""
    try:
        import webview
        if os.name == "nt":
            import webview.platforms.winforms as winforms
            if getattr(winforms, "renderer", "") != "edgechromium":
                print("  No hi ha WebView2: s'obri el navegador.")
                return False
    except Exception as e:  # noqa: BLE001
        if os.name == "nt" and FROZEN:
            print(f"  No s'ha pogut preparar la finestra ({e}): s'obri el navegador.")
        return False
    T = FINESTRA_TEXTOS[idioma]
    webview.settings["ALLOW_DOWNLOADS"] = True            # exportar partides
    webview.settings["OPEN_EXTERNAL_LINKS_IN_BROWSER"] = True
    w = webview.create_window(
        T["titol"], url, width=1360, height=880, min_size=(380, 520), confirm_close=not PROVA_FINESTRA,
        text_select=True, zoomable=True, background_color="#E9DCBC",
        localization={"global.quitConfirmation": T["tancar_q"], "global.saveFile": T["guardar"],
                      "global.ok": T["d_acord"], "global.cancel": T["cancel"], "global.quit": T["tancar"]})
    if PROVA_FINESTRA:
        def carregada():
            if Path(PROVA_FINESTRA).exists():
                return
            time.sleep(1)
            try:
                titol = w.evaluate_js("document.title")
            except Exception as e:  # noqa: BLE001
                titol = f"(no s'ha pogut llegir el títol: {e})"
            prova_feta(titol)
            w.destroy()
        w.events.loaded += carregada
    try:
        webview.start(gui="edgechromium" if os.name == "nt" else None, private_mode=False,
                      storage_path=str(dades_finestra()))
    except Exception as e:  # noqa: BLE001
        print(f"  No s'ha pogut obrir la finestra ({e}): s'obri el navegador.")
        return False
    return True


def _bwrap_funciona():
    """WebKitGTK aïlla les pàgines amb bubblewrap. Si el sistema no ho permet (passa en alguns Ubuntu 24.04),
    no es veuria res. Com que la finestra només mostra La Comunitat d'aquest ordinador, llavors es desactiva."""
    import shutil
    import subprocess
    bwrap = shutil.which("bwrap")
    if not bwrap:
        return True
    try:
        return subprocess.run([bwrap, "--ro-bind", "/", "/", "--unshare-user", "true"], stdout=subprocess.DEVNULL,
                              stderr=subprocess.DEVNULL, timeout=10).returncode == 0
    except (OSError, subprocess.SubprocessError):
        return True


def _finestra_gtk(url, idioma):
    """Linux: la finestra amb GTK 3 i WebKitGTK (paquets python3-gi i gir1.2-webkit2-4.1)."""
    os.environ.setdefault("WEBKIT_DISABLE_DMABUF_RENDERER", "1")   # evita finestres en blanc amb alguns controladors
    try:
        import gi
        gi.require_version("Gtk", "3.0")
        gi.require_version("GdkPixbuf", "2.0")
        try:
            gi.require_version("WebKit2", "4.1")
        except ValueError:
            gi.require_version("WebKit2", "4.0")
        from gi.repository import GdkPixbuf, Gio, GLib, Gtk, WebKit2
    except (ImportError, ValueError):
        return False
    GLib.set_prgname("comunitat-del-anell")      # lliga la finestra amb l'accés del menú
    GLib.set_application_name(FINESTRA_TEXTOS[idioma]["titol"])
    if not Gtk.init_check(None)[0]:
        return False
    if not _bwrap_funciona():
        os.environ["WEBKIT_DISABLE_SANDBOX_THIS_IS_DANGEROUS"] = "1"
    T = FINESTRA_TEXTOS[idioma]
    local = urlparse(url)

    def es_local(uri):
        u = urlparse(uri)
        return u.scheme in ("about", "data", "blob") or (
            u.scheme == "http" and u.hostname in ("localhost", "127.0.0.1") and u.port == local.port)

    def obri_fora(uri):
        if urlparse(uri).scheme in ("http", "https", "mailto", "file"):
            try:
                Gio.AppInfo.launch_default_for_uri(uri, None)
            except GLib.Error:
                pass

    dades = dades_finestra()
    gestor = WebKit2.WebsiteDataManager(base_data_directory=str(dades),
                                        base_cache_directory=str(dades / "memoria-cau"))
    context = WebKit2.WebContext.new_with_website_data_manager(gestor)

    win = Gtk.Window(title=T["titol"])
    win.set_default_size(1360, 880)
    win.set_size_request(380, 520)
    try:
        carrega = GdkPixbuf.PixbufLoader()
        carrega.write(base64.b64decode(ICONA_PNG))
        carrega.close()
        win.set_icon(carrega.get_pixbuf())
    except Exception:  # noqa: BLE001
        pass

    vista = WebKit2.WebView.new_with_context(context)
    s = vista.get_settings()
    s.set_enable_developer_extras(False)
    s.set_javascript_can_open_windows_automatically(False)
    win.add(vista)

    def avis(tipus, text, detall=""):
        d = Gtk.MessageDialog(transient_for=win, modal=True, message_type=tipus, buttons=Gtk.ButtonsType.OK, text=text)
        if detall:
            d.format_secondary_text(detall)
        d.run()
        d.destroy()

    # Què s'obri ací i què fora: només La Comunitat va a la finestra; la resta, al navegador habitual.
    def decideix(_v, decisio, tipus):
        if tipus in (WebKit2.PolicyDecisionType.NAVIGATION_ACTION, WebKit2.PolicyDecisionType.NEW_WINDOW_ACTION):
            uri = decisio.get_navigation_action().get_request().get_uri()
            if not es_local(uri):
                decisio.ignore()
                obri_fora(uri)
                return True
        elif tipus == WebKit2.PolicyDecisionType.RESPONSE and not decisio.is_mime_type_supported():
            decisio.download()           # les partides exportades es guarden a Baixades
            return True
        return False

    # Baixades: a la carpeta Baixades, sense sobreescriure res
    def desti(baixada, suggerit):
        carpeta = GLib.get_user_special_dir(GLib.UserDirectory.DIRECTORY_DOWNLOAD) or str(Path.home())
        os.makedirs(carpeta, exist_ok=True)
        nom = os.path.basename(suggerit or "") or "partida.json"
        base, ext = os.path.splitext(nom)
        cami, n = os.path.join(carpeta, nom), 1
        while os.path.exists(cami):
            n += 1
            cami = os.path.join(carpeta, f"{base} ({n}){ext}")
        baixada.cami = cami
        baixada.set_destination(GLib.filename_to_uri(cami, None))
        return True

    def feta(baixada):
        cami = getattr(baixada, "cami", None)
        if not cami or not os.path.exists(cami):
            return
        d = Gtk.MessageDialog(transient_for=win, modal=True, message_type=Gtk.MessageType.INFO,
                              buttons=Gtk.ButtonsType.NONE, text=T["guardat"])
        d.format_secondary_text(cami)
        d.add_button(T["obri_carpeta"], 1)
        d.add_button(T["d_acord"], Gtk.ResponseType.OK)
        if d.run() == 1:
            obrir_carpeta(os.path.dirname(cami))
        d.destroy()

    def baixada(_c, b):
        b.connect("decide-destination", desti)
        b.connect("finished", feta)
        b.connect("failed", lambda _b, error: avis(Gtk.MessageType.ERROR, T["no_guardat"], error.message))

    def titol(_v, _p):
        win.set_title(vista.get_title() or T["titol"])

    carregada = []

    def carrega_feta(_v, esdeveniment):
        if esdeveniment != WebKit2.LoadEvent.FINISHED or carregada:
            return
        carregada.append(1)
        if PROVA_FINESTRA:
            def acaba():
                prova_feta(vista.get_title() or "")
                win.destroy()
                return False
            GLib.timeout_add(1500, acaba)

    def tancant(_w, _e):
        if PROVA_FINESTRA:
            return False
        d = Gtk.MessageDialog(transient_for=win, modal=True, message_type=Gtk.MessageType.QUESTION,
                              buttons=Gtk.ButtonsType.NONE, text=T["tancar_t"])
        d.format_secondary_text(T["tancar_q"])
        d.add_button(T["cancel"], Gtk.ResponseType.CANCEL)
        d.add_button(T["tancar"], Gtk.ResponseType.OK)
        d.set_default_response(Gtk.ResponseType.OK)
        r = d.run()
        d.destroy()
        return r != Gtk.ResponseType.OK          # True = no la tanques

    context.connect("download-started", baixada)
    vista.connect("decide-policy", decideix)
    vista.connect("notify::title", titol)
    vista.connect("load-changed", carrega_feta)
    win.connect("delete-event", tancant)
    win.connect("destroy", lambda *_: Gtk.main_quit())
    try:  # en tancar la sessió o apagar l'ordinador, es tanca sense preguntar i es guarda tot
        import signal
        GLib.unix_signal_add(GLib.PRIORITY_DEFAULT, signal.SIGTERM, lambda: (Gtk.main_quit(), False)[1])
    except Exception:  # noqa: BLE001
        pass
    vista.load_uri(url)
    win.show_all()
    Gtk.main()
    return True


# ---------------------------------------------------------------- la finestreta de reserva (Tk)
def finestra_adreca(port, idioma, obrir_navegador):
    """La finestreta amb l'adreça, el QR i la partida oberta, per a quan no es pot obrir la finestra pròpia.
    L'app s'obri al navegador."""
    import tkinter as tk
    import tkinter.font as tkfont
    from tkinter import messagebox

    T = FINESTRA_TEXTOS[idioma]
    local = f"http://localhost:{port}"
    urls = lan_urls()

    root = tk.Tk(className="comunitat-del-anell")   # a Linux, lliga la finestra amb l'accés del menú
    root.title(T["titol"])
    root.resizable(False, False)
    try:
        root.iconphoto(True, tk.PhotoImage(data=ICONA_PNG))
    except Exception:  # noqa: BLE001
        pass

    # Colors i lletres del pergamí de l'app
    paper, carta, tinta, suau, linia, roig, or_, verd = ("#E9DCBC", "#F4EAD2", "#2A1C10", "#6F5A40",
                                                          "#C4AB80", "#8C2A1C", "#A27419", "#3E6A36")
    fams = set(tkfont.families(root))
    serif = next((f for f in ("Georgia", "Alegreya", "DejaVu Serif", "Liberation Serif", "Noto Serif",
                              "Times New Roman") if f in fams), "serif")
    F = lambda mida, gruix="normal": (serif, mida, gruix)  # noqa: E731
    root.configure(bg=paper)

    def boto(pare, text, ordre, principal=False):
        return tk.Button(pare, text=text, command=ordre, font=F(11, "bold" if principal else "normal"),
                         bg=roig if principal else carta, fg="#FBEFDA" if principal else tinta,
                         activebackground="#A33A2A" if principal else paper,
                         activeforeground="#FBEFDA" if principal else tinta,
                         relief="flat", bd=0, highlightthickness=1, highlightbackground=roig if principal else linia,
                         padx=14, pady=7, cursor="hand2")

    def copiar(text, b):
        root.clipboard_clear()
        root.clipboard_append(text)
        b.configure(text=T["copiat"])
        root.after(1500, lambda: b.configure(text=T["copiar"]))

    cos = tk.Frame(root, bg=paper, padx=22, pady=18)
    cos.pack(fill="both")

    # Capçalera
    cap = tk.Frame(cos, bg=paper)
    cap.pack(fill="x")
    try:
        logo = tk.PhotoImage(data=ICONA_PNG).subsample(2)
        tk.Label(cap, image=logo, bg=paper).pack(side="left", padx=(0, 12))
        cap.logo = logo
    except Exception:  # noqa: BLE001
        pass
    tit = tk.Frame(cap, bg=paper)
    tit.pack(side="left", fill="x")
    tk.Label(tit, text=T["titol"], font=F(19), fg=tinta, bg=paper).pack(anchor="w")
    estat = tk.Frame(tit, bg=paper)
    estat.pack(anchor="w")
    tk.Label(estat, text="●", font=F(11), fg=verd, bg=paper).pack(side="left")
    tk.Label(estat, text=" " + T["en_marxa"].format(v=VERSION), font=F(11), fg=suau, bg=paper).pack(side="left")

    # Targeta amb l'adreça i el QR
    carta_f = tk.Frame(cos, bg=carta, highlightthickness=1, highlightbackground=linia, padx=16, pady=14)
    carta_f.pack(fill="x", pady=(16, 10))
    tk.Label(carta_f, text=T["entrar"].upper(), font=F(9, "bold"), fg=or_, bg=carta).pack(anchor="w")
    if urls:
        fila = tk.Frame(carta_f, bg=carta)
        fila.pack(fill="x", pady=(6, 8))
        tk.Label(fila, text=urls[0], font=F(15, "bold"), fg=tinta, bg=carta).pack(side="left")
        bc = boto(fila, T["copiar"], lambda: copiar(urls[0], bc))
        bc.configure(padx=10, pady=3, font=F(10))
        bc.pack(side="right")
        m = qr_matrix(urls[0])
        n = len(m) + 8
        cel = max(3, 196 // n)
        qr = tk.Canvas(carta_f, width=n * cel, height=n * cel, bg="#FFFFFF", highlightthickness=0)
        for y, row in enumerate(m):
            for x, v in enumerate(row):
                if v:
                    qr.create_rectangle((x + 4) * cel, (y + 4) * cel, (x + 5) * cel, (y + 5) * cel, fill="#000000", width=0)
        qr.pack(pady=(2, 8))
        tk.Label(carta_f, text=T["escaneja"], font=F(10), fg=suau, bg=carta, wraplength=380, justify="left").pack(anchor="w")
        if len(urls) > 1:
            tk.Label(carta_f, text=T["altres"].format(u=", ".join(urls[1:])), font=F(9), fg=suau, bg=carta,
                     wraplength=380, justify="left").pack(anchor="w", pady=(4, 0))
    else:
        tk.Label(carta_f, text=T["sense_xarxa"], font=F(11), fg=roig, bg=carta, wraplength=380,
                 justify="left").pack(anchor="w", pady=(6, 0))

    # Partida oberta
    partida = tk.StringVar(value=camp_name(state["docs"], state["active"]))
    f = tk.Frame(cos, bg=paper)
    f.pack(fill="x", pady=3)
    tk.Label(f, text=T["partida"], font=F(11), fg=suau, bg=paper).pack(side="left")
    tk.Label(f, textvariable=partida, font=F(12, "bold"), fg=tinta, bg=paper).pack(side="right")

    # Botons
    botons = tk.Frame(cos, bg=paper)
    botons.pack(fill="x", pady=(14, 6))

    def aturar():
        if not messagebox.askokcancel(T["tancar_t"], T["tancar_q"], parent=root):
            return
        root.destroy()

    boto(botons, T["navegador"], lambda: webbrowser.open(local), principal=True).pack(side="left")
    boto(botons, T["carpeta"], lambda: obrir_carpeta(DATA_DIR)).pack(side="left", padx=8)
    boto(botons, T["aturar"], aturar).pack(side="right")
    tk.Label(cos, text=T["peu"], font=F(9), fg=suau, bg=paper).pack(anchor="w", pady=(8, 0))

    def refresca():
        with lock:
            partida.set(camp_name(state["docs"], state["active"]))
        root.after(2000, refresca)

    root.protocol("WM_DELETE_WINDOW", aturar)
    root.after(2000, refresca)
    if obrir_navegador:
        root.after(800, lambda: webbrowser.open(local))
    root.update_idletasks()
    w, h = root.winfo_reqwidth(), root.winfo_reqheight()
    root.geometry(f"+{max(0, (root.winfo_screenwidth() - w) // 2)}+{max(0, (root.winfo_screenheight() - h) // 3)}")
    root.mainloop()


def lan_addresses():
    ips = set()
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("10.255.255.255", 1))
        ips.add(s.getsockname()[0])
        s.close()
    except OSError:
        pass
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            ips.add(info[4][0])
    except OSError:
        pass
    return sorted(ip for ip in ips if not ip.startswith("127."))


def lan_urls():
    return [f"http://{ip}:{state['port']}" for ip in lan_addresses()]


# ---------------------------------------------------------------- HTTP
class Handler(BaseHTTPRequestHandler):
    server_version = "Comunitat/" + VERSION
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        pass

    def _send(self, code, body, ctype, extra=None):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    def _json(self, code, obj):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self._send(code, body, "application/json; charset=utf-8", {"Cache-Control": "no-store"})

    def _body(self):
        n = int(self.headers.get("Content-Length") or 0)
        if n > 2_000_000:
            raise ValueError("massa gran")
        return json.loads(self.rfile.read(n) or b"{}")

    def _query(self):
        return parse_qs(urlparse(self.path).query)

    def _session(self):
        tok = self.headers.get("X-Taula-Token") or (self._query().get("t") or [""])[0]
        with lock:
            return state["sessions"].get(tok)

    # -- GET
    def do_GET(self):
        route = self.path.split("?")[0]
        if route in ("/", "/index.html"):
            return self._send(200, PAGE_BYTES, "text/html; charset=utf-8",
                              {"Cache-Control": "no-store", "X-Taula-Version": VERSION})
        if route == "/mapa":
            lang = "es" if (self._query().get("lang") or ["val"])[0] == "es" else "val"
            body, ctype = map_image(lang)
            return self._send(200, body, ctype, {"Cache-Control": "no-cache"})
        if route == "/api/hello":
            out = {"taula": 1, "version": VERSION, "local": self._local()}
            if out["local"]:
                out["dades"] = str(DATA_DIR)
            return self._json(200, out)
        if route == "/api/invite":
            urls = lan_urls() or [f"http://localhost:{state['port']}"]
            return self._json(200, {"list": [{"url": u, "svg": qr_svg(u)} for u in urls]})
        sess = self._session()
        if route in ("/api/history", "/api/campaigns", "/api/snapshot", "/api/events", "/api/export") and not sess:
            return self._json(401, {"error": "Sessió no vàlida. Torna a entrar."})
        if route == "/api/history":
            with lock:
                return self._json(200, {"list": list(reversed(state["history"]))})
        if route == "/api/campaigns":
            with lock:
                return self._json(200, {"active": state["active"], "list": list_campaigns()})
        if route == "/api/snapshot":
            with lock:
                return self._json(200, {"me": {"uid": sess["uid"], "dm": True},
                                        "campaign": state["active"], "docs": snapshot()})
        if route == "/api/events":
            return self._events(sess)
        if route == "/api/export":
            return self._export()
        self._json(404, {"error": "No trobat"})

    def _local(self):
        """La petició ve d'aquest mateix ordinador (la finestra pròpia o un navegador en el servidor)?"""
        return self.client_address[0].startswith("127.") or self.client_address[0] == "::1"

    def _export(self):
        cid = (self._query().get("id") or [""])[0]
        with lock:
            if not re.fullmatch(r"[a-z0-9-]{1,60}", cid) or not camp_file(cid).exists():
                return self._json(404, {"error": "Aquesta partida ja no existeix."})
            if cid == state["active"]:
                save_now()
            name, blob = export_json(cid)
        fname = (slugify_plain(name) or "partida") + "-" + time.strftime("%Y%m%d") + ".json"
        # application/octet-stream perquè tots els navegadors i finestres el guarden com a fitxer
        return self._send(200, blob, "application/octet-stream",
                          {"Content-Disposition": f'attachment; filename="{fname}"', "Cache-Control": "no-store"})

    def _events(self, sess):
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Connection", "keep-alive")
        self.send_header("X-Accel-Buffering", "no")
        self.end_headers()
        # El farciment fa passar el flux pels antivirus i intermediaris que retenen les respostes curtes.
        try:
            self.wfile.write(b":" + b" " * 4096 + b"\nretry: 3000\n\n")
            self.wfile.flush()
        except OSError:
            return
        c = Client(sess)
        with lock:
            clients.append(c)
            first = {"me": {"uid": sess["uid"], "dm": True}, "campaign": state["active"], "docs": snapshot()}
        try:
            self._sse("snapshot", first)
            while True:
                try:
                    kind, payload = c.q.get(timeout=10)
                    self._sse(kind, payload)
                except queue.Empty:
                    self._sse("ping", {})
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError, OSError):
            pass
        finally:
            with lock:
                if c in clients:
                    clients.remove(c)

    def _sse(self, kind, payload):
        data = json.dumps(payload, ensure_ascii=False)
        self.wfile.write(f"event: {kind}\ndata: {data}\n\n".encode("utf-8"))
        self.wfile.flush()

    # -- POST
    def do_POST(self):
        route = self.path.split("?")[0]
        if route == "/api/import":
            return self._import()
        try:
            body = self._body()
        except Exception:  # noqa: BLE001
            return self._json(400, {"error": "Petició mal formada"})
        if route == "/api/join":
            return self._join(body)
        sess = self._session()
        if not sess:
            return self._json(401, {"error": "Sessió no vàlida. Torna a entrar."})
        if route == "/api/write":
            return self._write(body, sess)
        if route == "/api/campaigns":
            return self._campaigns(body)
        if route == "/api/history":
            return self._history(body)
        if route == "/api/carpeta":
            if not self._local():
                return self._json(403, {"error": "La carpeta de dades només es pot obrir des de l'ordinador principal."})
            DATA_DIR.mkdir(parents=True, exist_ok=True)
            obrir_carpeta(DATA_DIR)
            return self._json(200, {"ok": True, "dades": str(DATA_DIR)})
        self._json(404, {"error": "No trobat"})

    def _import(self):
        if not self._session():
            return self._json(401, {"error": "Sessió no vàlida. Torna a entrar."})
        n = int(self.headers.get("Content-Length") or 0)
        if n > MAX_IMPORT:
            return self._json(413, {"error": "El fitxer és massa gran."})
        data = self.rfile.read(n) if n else b""
        with lock:
            try:
                cid = import_campaign(data)
            except ImportError_ as e:
                return self._json(400, {"error": str(e)})
            result = {"active": state["active"], "list": list_campaigns(), "imported": cid}
        return self._json(200, result)

    def _join(self, body):
        name = str(body.get("name") or "").strip()[:40]
        old_tok = str(body.get("token") or "")
        with lock:
            sess = state["sessions"].get(old_tok)
            if sess:
                tok = old_tok
            else:
                if not name:
                    return self._json(400, {"error": "Escriu el teu nom."})
                tok = secrets.token_urlsafe(24)
                sess = {"uid": "u" + secrets.token_hex(6)}
                state["sessions"][tok] = sess
            if name:
                state["users"][sess["uid"]] = name
            dirty.set()
        if name:
            broadcast(["users/" + sess["uid"]])
        return self._json(200, {"token": tok, "uid": sess["uid"], "dm": True})

    def _write(self, body, sess):
        path, mode, data = body.get("path"), body.get("mode"), body.get("data")
        if not valid_path(path) or mode not in ("set", "update", "delete"):
            return self._json(400, {"error": "Petició mal formada"})
        if mode != "delete" and not isinstance(data, dict):
            return self._json(400, {"error": "Petició mal formada"})
        if mode != "delete" and len(json.dumps(data)) > 256_000:
            return self._json(413, {"error": "Document massa gran"})
        with lock:
            if body.get("camp") and body.get("camp") != state["active"]:
                return self._json(409, {"error": "S'ha obert una altra partida."})
            if not can_write(path, mode, sess):
                return self._json(403, {"error": "No tens permís per a canviar això."})
            if seg(path)[0] == "users":
                merged = deep_merge(get_doc(path) or {}, data) if mode == "update" else data
                state["users"][sess["uid"]] = str(merged.get("name") or "")[:40]
            else:
                docs = state["docs"]
                if mode == "delete":
                    docs.pop(path, None)
                elif mode == "set":
                    docs[path] = data
                else:
                    docs[path] = deep_merge(docs.get(path) or {}, data)
                if path == "game/state" and track_result(docs.get(path)):
                    save_history()
            dirty.set()
        broadcast([path])
        return self._json(200, {"ok": True})

    def _history(self, body):
        hid = str(body.get("id") or "")
        with lock:
            if body.get("action") == "delete":
                state["history"] = [h for h in state["history"] if h["id"] != hid]
                save_history()
            return self._json(200, {"list": list(reversed(state["history"]))})

    def _campaigns(self, body):
        action = body.get("action")
        name = str(body.get("name") or "").strip()[:80]
        cid = str(body.get("id") or "")
        if cid and not re.fullmatch(r"[a-z0-9-]{1,60}", cid):
            return self._json(400, {"error": "Partida desconeguda."})
        switched = False
        with lock:
            if action == "create":
                if not name:
                    return self._json(400, {"error": "Posa-li un nom a la partida."})
                save_now()
                activate(new_campaign(name))
                switched = True
            elif action == "switch":
                if not camp_file(cid).exists():
                    return self._json(404, {"error": "Aquesta partida ja no existeix."})
                if cid != state["active"]:
                    save_now()
                    activate(cid)
                    switched = True
            elif action == "duplicate":
                if not camp_file(cid).exists():
                    return self._json(404, {"error": "Aquesta partida ja no existeix."})
                save_now()
                docs = read_json(camp_file(cid)).get("docs", {})
                new_name = name or (camp_name(docs, cid) + " (còpia)")
                docs = dict(docs)
                docs["campaign/main"] = {**(docs.get("campaign/main") or {}), "name": new_name}
                write_json(camp_file(slugify(new_name)), {"docs": docs})
            elif action == "delete":
                if cid == state["active"]:
                    return self._json(400, {"error": "No pots esborrar la partida oberta. Obri'n una altra primer."})
                if not camp_file(cid).exists():
                    return self._json(404, {"error": "Aquesta partida ja no existeix."})
                TRASH_DIR.mkdir(exist_ok=True)
                camp_file(cid).replace(TRASH_DIR / f"{cid}-{time.strftime('%Y%m%d-%H%M%S')}.json")
            elif action == "backups":
                if not camp_file(cid).exists():
                    return self._json(404, {"error": "Aquesta partida ja no existeix."})
                return self._json(200, {"id": cid, "list": list_backups(cid)})
            elif action == "backup":
                if not camp_file(cid).exists():
                    return self._json(404, {"error": "Aquesta partida ja no existeix."})
                if cid == state["active"]:
                    save_now()
                make_backup(cid, campaign_docs(cid), "ma")
                return self._json(200, {"id": cid, "list": list_backups(cid)})
            elif action == "restore":
                bid = str(body.get("backup") or "")
                bf = backup_dir(cid) / f"{bid}.json"
                if not camp_file(cid).exists() or not BACKUP_RE.fullmatch(bid) or not bf.exists():
                    return self._json(404, {"error": "Aquesta còpia ja no existeix."})
                try:
                    docs = check_docs(read_json(bf).get("docs"))
                except Exception:  # noqa: BLE001
                    return self._json(400, {"error": "La còpia està danyada."})
                make_backup(cid, campaign_docs(cid), "abans")     # per si de cas, una còpia del que hi havia
                if cid == state["active"]:
                    state["docs"] = docs
                    save_now()
                    switched = True
                else:
                    write_json(camp_file(cid), {"docs": docs})
            else:
                return self._json(400, {"error": "Acció desconeguda."})
            dirty.set()
            result = {"active": state["active"], "list": list_campaigns()}
        if switched:
            save_now()
            broadcast_event("campaign", {"id": state["active"]})
        return self._json(200, result)


class Server(ThreadingHTTPServer):
    daemon_threads = True

    def handle_error(self, request, client_address):
        if isinstance(sys.exc_info()[1], (BrokenPipeError, ConnectionResetError, ConnectionAbortedError)):
            return
        super().handle_error(request, client_address)


def main():
    for name in ("stdout", "stderr"):  # l'executable de Windows no té terminal
        if getattr(sys, name) is None:
            setattr(sys, name, open(os.devnull, "w", encoding="utf-8"))
    for stream in (sys.stdout, sys.stderr):  # les consoles de Windows potser no parlen UTF-8
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")
        except Exception:  # noqa: BLE001
            pass
    if os.name == "nt":
        os.system("")  # activa els colors ANSI de la consola de Windows (per al QR)
    ap = argparse.ArgumentParser(description="Servidor local de La Comunitat")
    ap.add_argument("--port", type=int, default=8766)
    ap.add_argument("--partida", default="", help="nom de la partida que s'obri en arrancar (la crea si no existeix)")
    ap.add_argument("--dades", default=os.environ.get("COMUNITAT_DADES", ""),
                    help="carpeta on es guarden les partides (per defecte, al costat del programa, "
                         "o a la carpeta de l'usuari si està instal·lat)")
    ap.add_argument("--navegador", action="store_true",
                    help="obri l'app al navegador, amb la finestreta de l'adreça i el QR, en compte de la finestra pròpia")
    ap.add_argument("--sense-finestra", action="store_true", help="no obri cap finestra: només el terminal")
    ap.add_argument("--sense-navegador", action="store_true", help="no obri el navegador en arrancar")
    ap.add_argument("--sense-qr", action="store_true", help="no mostra el codi QR al terminal")
    ap.add_argument("--idioma", choices=("ca", "es"), default="ca",
                    help="idioma de les finestres i els avisos: ca (valencià, per defecte) o es (castellà)")
    a = ap.parse_args()
    if a.dades.strip():
        set_data_dir(a.dades.strip())
    pantalla = not a.sense_finestra and hi_ha_pantalla()
    idioma = a.idioma
    state["port"] = a.port
    try:
        srv = Server(("0.0.0.0", a.port), Handler)
    except OSError:
        print(f"\n  El port {a.port} ja està en ús: hi ha un altre programa (potser La Comunitat ja oberta) escoltant-hi.\n"
              f"  Tanca'l, o arranca en un altre port:   python3 comunitat.py --port 9001\n")
        if pantalla:
            T = FINESTRA_TEXTOS[idioma]
            avis_finestra(T["port_t"], T["port_q"].format(p=a.port))
        sys.exit(1)
    load(a.partida.strip() or None)
    load_history()
    threading.Thread(target=saver, daemon=True).start()
    try:  # en apagar l'ordinador o tancar la sessió (Linux), es guarda igual que amb Ctrl+C
        import signal
        signal.signal(signal.SIGTERM, lambda *_: (_ for _ in ()).throw(KeyboardInterrupt()))
    except Exception:  # noqa: BLE001
        pass
    print(f"\n  La Comunitat (versió {VERSION}) està en marxa.\n")
    print(f"  En aquest ordinador:   http://localhost:{a.port}")
    urls = lan_urls()
    for u in urls:
        print(f"  Des de la xarxa:       {u}")
    print()
    print(f"  Partida oberta:         {camp_name(state['docs'], state['active'])}")
    print(f"  Dades guardades a:      {DATA_DIR}")

    def mostra_qr():
        if urls and not a.sense_qr:
            print("\n  Escaneja aquest codi amb el mòbil per a entrar:\n")
            try:
                print(qr_terminal(urls[0]))
            except Exception:  # noqa: BLE001
                pass

    threading.Thread(target=srv.serve_forever, daemon=True).start()
    try:
        feta = False
        if pantalla and not a.navegador:
            print("\n  S'obri la finestra de La Comunitat. Tanca-la per a aturar-la.\n")
            feta = finestra_app(a.port, idioma)
        if not feta and pantalla and hi_ha_finestra():
            print("\n  Tanca la finestreta de La Comunitat per a aturar-la.\n")
            finestra_adreca(a.port, idioma, obrir_navegador=not a.sense_navegador)
            feta = True
        if not feta:
            mostra_qr()
            print("\n  Prem Ctrl+C per a aturar-la" + (" o tanca aquesta finestra" if os.name == "nt" else "") + ".\n")
            if pantalla and not a.sense_navegador:
                threading.Timer(1.0, lambda: webbrowser.open(f"http://localhost:{a.port}")).start()
            while True:
                time.sleep(3600)
    except KeyboardInterrupt:
        pass
    finally:
        srv.shutdown()
        save_now()
        print("\n  Partida guardada. Fins la pròxima!\n")


